// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IV3PoolLike {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function fee() external view returns (uint24);

    function slot0()
    external
    view
    returns (
        uint160 sqrtPriceX96,
        int24 tick,
        uint16,
        uint16,
        uint16,
        uint8,
        bool unlocked
    );

    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}

interface IUniswapV3SwapCallback {
    function uniswapV3SwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata data) external;
}

contract PoolIdQuoterV3 is IUniswapV3SwapCallback {
    error NotFromPool();
    error TokenNotInPool();
    error InvalidAmount();
    error QuoteResult(int256 amount0Delta, int256 amount1Delta);

    // TickMath constants
    uint160 internal constant MIN_SQRT_RATIO = 4295128739;
    uint160 internal constant MAX_SQRT_RATIO = 1461446703485210103287273052203988822378723970342;

    bytes4 private constant QUOTE_RESULT_SELECTOR =
    bytes4(keccak256("QuoteResult(int256,int256)"));

    // ----------------------------
    // New "Base/Quote" API
    // ----------------------------

    struct QuoteBaseParams {
        address pool;
        address baseToken;          // e.g. USDC
        address quoteToken;         // e.g. WETH
        uint256 amountBase;         // always in baseToken units/decimals
        uint160 sqrtPriceLimitX96;  // 0 => auto no-limit (per direction)
    }

    struct QuoteExactInLike {
        uint256 amountOut;              // quote received for amountBase base
        uint160 sqrtPriceX96After;      // after sim
        uint32 initializedTicksCrossed; // 0 (not implemented)
        uint256 gasEstimate;            // gas used by sim
    }

    struct QuoteExactOutLike {
        uint256 amountIn;               // quote required to receive amountBase base
        uint160 sqrtPriceX96After;      // after sim
        uint32 initializedTicksCrossed; // 0 (not implemented)
        uint256 gasEstimate;            // gas used by sim
    }

    struct QuoteBothBaseResult {
        uint256 blockNumber;

        address pool;
        address token0;
        address token1;
        uint24 fee;

        uint160 sqrtPriceX96Before;
        int24 tickBefore;

        QuoteExactInLike exactIn;
        QuoteExactOutLike exactOut;
    }

    // ----------------------------
    // Existing "rich" API (kept)
    // ----------------------------

    struct QuoteRequest {
        address baseToken;
        address quoteToken;
        address pool;
        uint256 amountBase;
        uint160 sqrtPriceLimitX96; // can be 0 => auto no-limit
    }

    struct QuoteResponse {
        uint256 blockNumber;

        address pool;
        address token0;
        address token1;
        uint24 fee;

        uint160 sqrtPriceX96;
        int24 tick;

        uint256 amountOutQuote;
        uint256 gasUsedExactIn;

        uint256 amountInQuoteForBase;
        uint256 gasUsedExactOut;
    }

    function quoteByPoolId(QuoteRequest calldata r) external returns (QuoteResponse memory out) {
        if (r.amountBase == 0) revert InvalidAmount();

        out.blockNumber = block.number;
        out.pool = r.pool;

        out.token0 = IV3PoolLike(r.pool).token0();
        out.token1 = IV3PoolLike(r.pool).token1();
        out.fee = IV3PoolLike(r.pool).fee();

        (out.sqrtPriceX96, out.tick, , , , ,) = IV3PoolLike(r.pool).slot0();

        (out.amountOutQuote, out.gasUsedExactIn) = _quoteExactInputByPool(
            r.pool,
            r.baseToken,
            r.quoteToken,
            r.amountBase,
            r.sqrtPriceLimitX96
        );

        (out.amountInQuoteForBase, out.gasUsedExactOut) = _quoteExactOutputByPool(
            r.pool,
            r.baseToken,
            r.quoteToken,
            r.amountBase,
            r.sqrtPriceLimitX96
        );

        return out;
    }

    // ----------------------------
    // New functions
    // ----------------------------

    function quoteExactInBase(QuoteBaseParams calldata p)
    external
    returns (QuoteExactInLike memory r)
    {
        if (p.amountBase == 0) revert InvalidAmount();

        (uint256 outQuote, uint256 gasUsed, uint160 sqrtAfter) = _quoteExactInputByPoolWithAfter(
            p.pool,
            p.baseToken,
            p.quoteToken,
            p.amountBase,
            p.sqrtPriceLimitX96
        );

        r.amountOut = outQuote;
        r.sqrtPriceX96After = sqrtAfter;
        r.initializedTicksCrossed = 0;
        r.gasEstimate = gasUsed;
    }

    function quoteExactOutBase(QuoteBaseParams calldata p)
    external
    returns (QuoteExactOutLike memory r)
    {
        if (p.amountBase == 0) revert InvalidAmount();

        (uint256 inQuote, uint256 gasUsed, uint160 sqrtAfter) = _quoteExactOutputByPoolWithAfter(
            p.pool,
            p.baseToken,
            p.quoteToken,
            p.amountBase,
            p.sqrtPriceLimitX96
        );

        r.amountIn = inQuote;
        r.sqrtPriceX96After = sqrtAfter;
        r.initializedTicksCrossed = 0;
        r.gasEstimate = gasUsed;
    }

    function quoteBothBase(QuoteBaseParams calldata p)
    external
    returns (QuoteBothBaseResult memory out)
    {
        if (p.amountBase == 0) revert InvalidAmount();

        out.blockNumber = block.number;
        out.pool = p.pool;

        out.token0 = IV3PoolLike(p.pool).token0();
        out.token1 = IV3PoolLike(p.pool).token1();
        out.fee = IV3PoolLike(p.pool).fee();

        (out.sqrtPriceX96Before, out.tickBefore, , , , ,) = IV3PoolLike(p.pool).slot0();

        // exact in: base -> quote
        (uint256 outQuote, uint256 gasIn, uint160 sqrtAfterIn) = _quoteExactInputByPoolWithAfter(
            p.pool,
            p.baseToken,
            p.quoteToken,
            p.amountBase,
            p.sqrtPriceLimitX96
        );

        out.exactIn = QuoteExactInLike({
            amountOut: outQuote,
            sqrtPriceX96After: sqrtAfterIn,
            initializedTicksCrossed: 0,
            gasEstimate: gasIn
        });

        // exact out: quote -> base (need quote to receive amountBase base)
        (uint256 inQuote, uint256 gasOut, uint160 sqrtAfterOut) = _quoteExactOutputByPoolWithAfter(
            p.pool,
            p.baseToken,
            p.quoteToken,
            p.amountBase,
            p.sqrtPriceLimitX96
        );

        out.exactOut = QuoteExactOutLike({
            amountIn: inQuote,
            sqrtPriceX96After: sqrtAfterOut,
            initializedTicksCrossed: 0,
            gasEstimate: gasOut
        });
    }

    // ----------------------------
    // Internals (original + "with after")
    // ----------------------------

    function _quoteExactInputByPool(
        address pool,
        address baseToken,
        address quoteToken,
        uint256 amountInBase,
        uint160 sqrtPriceLimitX96
    ) internal returns (uint256 amountOutQuote, uint256 gasUsed) {
        uint256 gasStart = gasleft();

        (address t0, address t1) = (IV3PoolLike(pool).token0(), IV3PoolLike(pool).token1());
        bool baseIsT0 = baseToken == t0;
        bool baseIsT1 = baseToken == t1;
        bool quoteIsT0 = quoteToken == t0;
        bool quoteIsT1 = quoteToken == t1;

        if (!((baseIsT0 && quoteIsT1) || (baseIsT1 && quoteIsT0))) revert TokenNotInPool();

        bool zeroForOne = baseIsT0; // token0 -> token1

        uint160 limit = sqrtPriceLimitX96;
        if (limit == 0) {
            limit = zeroForOne ? (MIN_SQRT_RATIO + 1) : (MAX_SQRT_RATIO - 1);
        }

        try IV3PoolLike(pool).swap(
            address(this),
            zeroForOne,
            int256(amountInBase),
            limit,
            abi.encode(pool)
        ) returns (int256, int256) {
            // unreachable
            return (0, gasStart - gasleft());
        } catch (bytes memory reason) {
            (bool ok, int256 a0, int256 a1) = _tryDecodeQuoteResult(reason);
            if (!ok) _revertBytes(reason);

            int256 outDelta = zeroForOne ? a1 : a0;
            amountOutQuote = uint256(-outDelta);
            gasUsed = gasStart - gasleft();
        }
    }

    function _quoteExactOutputByPool(
        address pool,
        address baseToken,
        address quoteToken,
        uint256 amountOutBase,
        uint160 sqrtPriceLimitX96
    ) internal returns (uint256 amountInQuote, uint256 gasUsed) {
        uint256 gasStart = gasleft();

        (address t0, address t1) = (IV3PoolLike(pool).token0(), IV3PoolLike(pool).token1());
        bool baseIsT0 = baseToken == t0;
        bool baseIsT1 = baseToken == t1;
        bool quoteIsT0 = quoteToken == t0;
        bool quoteIsT1 = quoteToken == t1;

        if (!((baseIsT0 && quoteIsT1) || (baseIsT1 && quoteIsT0))) revert TokenNotInPool();

        // want base OUT => direction depends on whether base is token0 or token1
        bool zeroForOne = baseIsT1; // if base is token1, swap token0->token1 gives base out

        uint160 limit = sqrtPriceLimitX96;
        if (limit == 0) {
            limit = zeroForOne ? (MIN_SQRT_RATIO + 1) : (MAX_SQRT_RATIO - 1);
        }

        try IV3PoolLike(pool).swap(
            address(this),
            zeroForOne,
            -int256(amountOutBase),
            limit,
            abi.encode(pool)
        ) returns (int256, int256) {
            // unreachable
            return (0, gasStart - gasleft());
        } catch (bytes memory reason) {
            (bool ok, int256 a0, int256 a1) = _tryDecodeQuoteResult(reason);
            if (!ok) _revertBytes(reason);

            int256 inDelta = zeroForOne ? a0 : a1;
            amountInQuote = uint256(inDelta);
            gasUsed = gasStart - gasleft();
        }
    }

    function _quoteExactInputByPoolWithAfter(
        address pool,
        address baseToken,
        address quoteToken,
        uint256 amountInBase,
        uint160 sqrtPriceLimitX96
    ) internal returns (uint256 amountOutQuote, uint256 gasUsed, uint160 sqrtAfter) {
        (amountOutQuote, gasUsed) = _quoteExactInputByPool(pool, baseToken, quoteToken, amountInBase, sqrtPriceLimitX96);
        (sqrtAfter, , , , , ,) = IV3PoolLike(pool).slot0();
    }

    function _quoteExactOutputByPoolWithAfter(
        address pool,
        address baseToken,
        address quoteToken,
        uint256 amountOutBase,
        uint160 sqrtPriceLimitX96
    ) internal returns (uint256 amountInQuote, uint256 gasUsed, uint160 sqrtAfter) {
        (amountInQuote, gasUsed) = _quoteExactOutputByPool(pool, baseToken, quoteToken, amountOutBase, sqrtPriceLimitX96);
        (sqrtAfter, , , , , ,) = IV3PoolLike(pool).slot0();
    }

    // ----------------------------
    // Callback + revert decoding
    // ----------------------------

    function uniswapV3SwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata data) external override {
        address pool = abi.decode(data, (address));
        if (msg.sender != pool) revert NotFromPool();
        revert QuoteResult(amount0Delta, amount1Delta);
    }

    function _tryDecodeQuoteResult(bytes memory reason) internal pure returns (bool ok, int256 a0, int256 a1) {
        if (reason.length != 4 + 32 + 32) return (false, 0, 0);

        bytes4 sel;
        assembly { sel := mload(add(reason, 32)) }
        if (sel != QUOTE_RESULT_SELECTOR) return (false, 0, 0);

        assembly {
            a0 := mload(add(reason, 36))
            a1 := mload(add(reason, 68))
        }
        return (true, a0, a1);
    }

    function _revertBytes(bytes memory reason) internal pure {
        assembly {
            revert(add(reason, 32), mload(reason))
        }
    }
}
